import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Backed by the signed-in Clerk session. Clerk's user id is the source of
// truth; on first sight of a given id we lazily create (or otherwise match by
// email) a row in our own in-memory user list, so the rest of the app keeps
// working against the plain `User` type instead of Clerk's.
export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;

  const email = clerkUser.primaryEmailAddress?.emailAddress ?? clerkUser.emailAddresses[0]?.emailAddress ?? "";

  let user = users.find((u) => u.id === clerkUser.id || u.email === email);
  if (!user) {
    const name =
      [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") ||
      clerkUser.username ||
      email ||
      "New user";

    user = {
      id: clerkUser.id,
      email,
      name,
      createdAt: new Date(clerkUser.createdAt).toISOString().slice(0, 10),
    };
    users.push(user);
  }

  return user;
}

